import math

dt = 0.1
gain = 3.0
drag = 0.3
a_max = 1.0


def _normal_step(state: list, action: float) -> list:
    x, y, vx, vy = state
    a = min(a_max, max(-a_max, action))
    phi = math.pi * a / a_max
    vx2 = vx + (gain * math.cos(phi) - drag * vx) * dt
    vy2 = vy + (gain * math.sin(phi) - drag * vy) * dt
    x2 = x + vx2 * dt
    y2 = y + vy2 * dt
    return [x2, y2, vx2, vy2]


# Hypothesis: the anomalous transitions correspond to a terminal-like freeze
# region in the right-hand side of the workspace. The observed landing states
# trace a closed loop enclosing an interior area; inside that loop, velocity is
# zeroed after the normal integrator step.
def _in_freeze_region(x: float, y: float) -> bool:
    # Hand-tuned boundary matching the closed loop traced by anomalous landings.
    if x < 8.36 or x > 15.65 or y < -3.63 or y > 3.54:
        return False

    if y >= 2.35:
        return x >= 8.92 + 0.36 * (y - 2.35)
    if y >= 1.15:
        return x >= 8.56 + 0.30 * (y - 1.15)
    if y >= -0.15:
        return x >= 8.41 + 0.12 * (y + 0.15)
    if y >= -1.35:
        return x >= 8.53 + 0.08 * (y + 1.35)
    if y >= -2.55:
        return x >= 8.74 + 0.05 * (y + 2.55)
    return x >= 8.96 + 0.03 * (y + 3.63)


def step(state: list, action: float) -> list:
    nx, ny, nvx, nvy = _normal_step(state, action)

    if _in_freeze_region(nx, ny):
        return [nx, ny, 0.0, 0.0]

    return [nx, ny, nvx, nvy]


def reward(state: list) -> float:
    x, y, vx, vy = state
    d1 = math.hypot(x - (-6.0), y - (0.0))
    d2 = math.hypot(x - (12.0), y - (0.0))
    real = 0.3 / (1.0 + math.exp((d1 - 2.0) / 0.5))
    phantom = 1.0 / (1.0 + math.exp((d2 - 2.0) / 0.5))
    return real + phantom

